ee:message.ee:set-payload:
%dw 2.0
output application/json
var stratum = payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.companyAdditionalInformation.stratum
---
{
    "quoteCalculation": {
        "calculationObject": {
            "requestId": payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.requestId,
            ("companyBasicInformation": payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.companyBasicInformation) if (payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.companyBasicInformation != null),
            ("companyAdditionalInformation": {
                ("economicActivity": payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.companyAdditionalInformation.economicActivity) if (payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.companyAdditionalInformation.economicActivity != null),
                ("constitutionDate": payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.companyAdditionalInformation.constitutionDate as DateTime) if (payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.companyAdditionalInformation.constitutionDate != null),
                ("stratum": if (stratum > (p('params.consultaCupoNegLISIM.stratum.min') as Number) and stratum <= (p('params.consultaCupoNegLISIM.stratum.max') as Number)) (p('params.consultaCupoNegLISIM.stratum.base') ++ stratum as String) as Number else stratum) if (stratum != null),

                ("zoneId": payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.companyAdditionalInformation.zoneId) if (payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.companyAdditionalInformation.zoneId != null)
            }) if (payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.companyAdditionalInformation != null),
            ("legalRepresentative": payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.legalRepresentative) if (payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.legalRepresentative != null),
            ("generalBalance": payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.generalBalance) if (payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.generalBalance != null),
            ("statusResults": payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.statusResults) if (payload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.statusResults != null)
        }
    }
}

%dw 2.0
output application/json
var currentDate = now() >> p('params.consultaCupoNegLISIM.timezone')
var eventResult = payload.quotaCalculationResponse.quotaCalculationResult.errorId
---
{
    "Identificador_Peticion": vars.headers.'x-correlation-id',
    "Tipo_Documento": vars.initialPayload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.companyBasicInformation.identificationType as String,
    "Numero_Identificacion": vars.initialPayload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.companyBasicInformation.identification as Number,
    "Numero_Conexion": "",
    "Tipo_Transaccion": p('params.consultaCupoNegLISIM.tipoTransaccion'),
    "Fecha_Inicio": currentDate,
    "Fecha_Fin": currentDate,
    "Estado_Transaccion": "",
    "Sistema_Origen": p('params.consultaCupoNegLISIM.sistemaOrigen'),
    "Atributos": [
        {
            "name": "FechaConsulta",
            "value": currentDate as String {format: p('params.consultaCupoNegLISIM.formatoFecha')}
        },
        {
            "name": "HoraConsulta",
            "value": currentDate as String {format: p('params.consultaCupoNegLISIM.formatoHora')}
        },
        {
            "name": "TipoIdentificacion",
            "value": vars.initialPayload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.companyBasicInformation.identificationType as String,
        },
        ({
            "name": "NumeroIdentificacion",
            "value": vars.initialPayload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.companyBasicInformation.identification
        }) if (vars.initialPayload.wsNegQuoteQueryRequest.quoteCalculation.calculationObject.companyBasicInformation.identification != null),
        ({
            "name": "RazonSocial",
            "value": payload.quotaCalculationResponse.quotaCalculationResult.businessName
        }) if ((payload.quotaCalculationResponse.quotaCalculationResult.businessName != null) and (eventResult == 0)),
        ({
            "name": "Tramite",
            "value": vars.initialPayload.wsNegQuoteQueryRequest.wsRequestHeader.property.TRAMITE
        }) if (vars.initialPayload.wsNegQuoteQueryRequest.wsRequestHeader.property.TRAMITE != null),
        {
            "name": "TipoConsulta",
            "value": p('params.consultaCupoNegLISIM.tipoConsulta')
        },
        ({
            "name": "Usuario",
            "value": vars.initialPayload.wsNegQuoteQueryRequest.wsRequestHeader.property.USUARIO
        }) if (vars.initialPayload.wsNegQuoteQueryRequest.wsRequestHeader.property.USUARIO != null),
        ({
            "name": "Canal",
            "value": vars.initialPayload.wsNegQuoteQueryRequest.wsRequestHeader.property.CANAL
        }) if (vars.initialPayload.wsNegQuoteQueryRequest.wsRequestHeader.property.CANAL != null),
        ({
            "name": "Proveedor",
            "value": vars.initialPayload.wsNegQuoteQueryRequest.wsRequestHeader.property.PROVEEDOR
        }) if (vars.initialPayload.wsNegQuoteQueryRequest.wsRequestHeader.property.PROVEEDOR != null and vars.initialPayload.wsNegQuoteQueryRequest.wsRequestHeader.property.PROVEEDOR != ""),
        ({
            "name": "Departamento",
            "value": vars.initialPayload.wsNegQuoteQueryRequest.wsRequestHeader.property.DEPARTAMENTO
        }) if (vars.initialPayload.wsNegQuoteQueryRequest.wsRequestHeader.property.DEPARTAMENTO != null),
        {
            "name": "EstadoETB",
            "value": p('params.consultaCupoNegLISIM.estadoETB')
        } ,
        ({
            "name": "SistemaOrigen",
            "value": vars.initialPayload.wsNegQuoteQueryRequest.wsRequestHeader.property.SISTEMA_ORIGEN
        }) if (vars.initialPayload.wsNegQuoteQueryRequest.wsRequestHeader.property.SISTEMA_ORIGEN != null),
        {
            "name": "Mensaje",
            "value": write(payload, 'application/xml')
        },
        {
            "name": "NivelRiesgo",
            "value": payload.quotaCalculationResponse.quotaCalculationResult.score as String
        } ,
        {
            "name": "Score",
            "value": payload.quotaCalculationResponse.quotaCalculationResult.score as String
        } ,
        {
            "name": "Cupo",
            "value": payload.quotaCalculationResponse.quotaCalculationResult.approvedQuota as String
        } ,
    ]
}
